// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title CommissionManager
 * @notice Charges a flat fee (default: 1 H2O) on each registered transaction
 *         and distributes it across the ecosystem:
 *           - poolShareBps   → deposited into the staking reward pool
 *           - ownerShareBps  → split equally among owners
 *           - remainder      → kept in contract buffer
 *
 *   Any contract in the ecosystem can call `chargeCommission(user)` to pull
 *   1 H2O (or configured amount) from the user and distribute it.
 *   The user must have previously approved this contract for the token.
 *
 *   Owners can:
 *   - Change the flat commission amount
 *   - Change the distribution percentages
 *   - Connect / disconnect contracts that are authorized to charge commissions
 *   - Add / remove owners
 *   - Emergency pause + withdraw
 */

interface IERC20Comm {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IRewardPool {
    function depositRewards(uint256 amount) external;
}

contract CommissionManager {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS       = 10_000;
    uint256 public constant MAX_OWNERS    = 5;
    uint256 public constant MAX_CONTRACTS = 20;

    // ─── Config ───────────────────────────────────────────────────────────────
    address public token;

    /// Flat commission per transaction (default 1 H2O = 1e18 if 18 decimals).
    uint256 public commissionAmount = 1e18;

    /// Basis points of the commission that go to the staking reward pool.
    uint256 public poolShareBps = 6_000;    // 60%
    /// Basis points that go to owner wallets.
    uint256 public ownerShareBps = 3_000;   // 30%
    /// Remainder (10%) stays in contract as buffer.

    /// Staking contract address that receives pool share via depositRewards().
    address public rewardPoolContract;

    // ─── Owner & Access ───────────────────────────────────────────────────────
    address[] public owners;

    /// Only these contracts are authorized to call chargeCommission().
    mapping(address => bool) public authorizedCallers;
    address[] public callerList;

    bool public paused;

    // ─── Stats ────────────────────────────────────────────────────────────────
    uint256 public totalCollected;
    uint256 public totalTransactions;

    // ─── Events ───────────────────────────────────────────────────────────────
    event CommissionCharged(address indexed user, address indexed caller, uint256 amount);
    event Distributed(uint256 toPool, uint256 toOwners, uint256 retained);
    event CallerAuthorized(address indexed caller);
    event CallerRevoked(address indexed caller);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event ConfigUpdated(uint256 commissionAmount, uint256 poolShareBps, uint256 ownerShareBps);
    event RewardPoolSet(address indexed pool);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "CommissionManager: not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender] || _isOwner(msg.sender), "CommissionManager: unauthorized");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "CommissionManager: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _token, address _initialOwner) {
        require(_token != address(0), "zero token");
        require(_initialOwner != address(0), "zero owner");
        token = _token;
        owners.push(_initialOwner);
    }

    // ─── Commission ───────────────────────────────────────────────────────────

    /**
     * @notice Charge `commissionAmount` tokens from `user`.
     *         Called by authorized ecosystem contracts on behalf of a user.
     *         User must have approved this contract for at least `commissionAmount`.
     */
    function chargeCommission(address user) external onlyAuthorized whenNotPaused returns (uint256 charged) {
        require(user != address(0), "zero user");
        charged = commissionAmount;
        if (charged == 0) return 0;

        require(
            IERC20Comm(token).transferFrom(user, address(this), charged),
            "CommissionManager: transfer failed"
        );

        totalCollected += charged;
        totalTransactions += 1;

        emit CommissionCharged(user, msg.sender, charged);
        _distribute(charged);
    }

    /**
     * @notice Anyone can manually fund the commission pool.
     *         Triggers distribution immediately.
     */
    function fund(uint256 amount) external whenNotPaused {
        require(amount > 0, "zero amount");
        require(IERC20Comm(token).transferFrom(msg.sender, address(this), amount), "transfer failed");
        totalCollected += amount;
        _distribute(amount);
    }

    // ─── Distribution ─────────────────────────────────────────────────────────

    function _distribute(uint256 amount) internal {
        uint256 toPool    = (amount * poolShareBps)  / MAX_BPS;
        uint256 toOwners  = (amount * ownerShareBps) / MAX_BPS;
        uint256 retained  = amount - toPool - toOwners;

        // Forward to staking reward pool
        if (toPool > 0 && rewardPoolContract != address(0)) {
            IERC20Comm(token).transfer(rewardPoolContract, toPool);
            try IRewardPool(rewardPoolContract).depositRewards(toPool) {} catch {}
        } else {
            retained += toPool;
        }

        // Split among owners
        if (toOwners > 0 && owners.length > 0) {
            uint256 perOwner = toOwners / owners.length;
            uint256 dust = toOwners - perOwner * owners.length;
            for (uint256 i = 0; i < owners.length; i++) {
                if (owners[i] != address(0) && perOwner > 0) {
                    IERC20Comm(token).transfer(owners[i], perOwner);
                }
            }
            retained += dust;
        }

        emit Distributed(toPool, toOwners, retained);
    }

    /**
     * @notice Distribute the contract's current idle balance.
     */
    function distributeBalance() external onlyOwner {
        uint256 bal = IERC20Comm(token).balanceOf(address(this));
        require(bal > 0, "nothing");
        _distribute(bal);
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    function setConfig(
        uint256 _commissionAmount,
        uint256 _poolShareBps,
        uint256 _ownerShareBps
    ) external onlyOwner {
        require(_poolShareBps + _ownerShareBps <= MAX_BPS, "exceeds 100%");
        commissionAmount = _commissionAmount;
        poolShareBps     = _poolShareBps;
        ownerShareBps    = _ownerShareBps;
        emit ConfigUpdated(_commissionAmount, _poolShareBps, _ownerShareBps);
    }

    function setRewardPool(address _pool) external onlyOwner {
        rewardPoolContract = _pool;
        emit RewardPoolSet(_pool);
    }

    // ─── Caller Authorization ─────────────────────────────────────────────────

    function authorizeCaller(address caller) external onlyOwner {
        require(caller != address(0), "zero address");
        require(!authorizedCallers[caller], "already authorized");
        require(callerList.length < MAX_CONTRACTS, "max callers");
        authorizedCallers[caller] = true;
        callerList.push(caller);
        emit CallerAuthorized(caller);
    }

    function revokeCaller(address caller) external onlyOwner {
        authorizedCallers[caller] = false;
        // Remove from list
        for (uint256 i = 0; i < callerList.length; i++) {
            if (callerList[i] == caller) {
                callerList[i] = callerList[callerList.length - 1];
                callerList.pop();
                break;
            }
        }
        emit CallerRevoked(caller);
    }

    function getAuthorizedCallers() external view returns (address[] memory) {
        return callerList;
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause / Emergency ────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "zero address");
        IERC20Comm(token).transfer(to, amount);
    }

    // ─── Views ────────────────────────────────────────────────────────────────

    function getStats() external view returns (
        uint256 collected,
        uint256 transactions,
        uint256 contractBalance
    ) {
        return (
            totalCollected,
            totalTransactions,
            IERC20Comm(token).balanceOf(address(this))
        );
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }
}

contracts/FundManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title FundManager
 * @notice Central hub that receives fees/funding and distributes them across
 *         the ecosystem according to configurable percentages:
 *           - rewardFundBps  → forwarded to the NewH2OStaking reward pool
 *           - ownerWalletBps → split equally among all owners
 *           - remainder      → kept in contract (manual emergency use)
 *
 * Anyone (users, other contracts, owners) can call `fund()` or send ETH/tokens.
 * Owners can connect / disconnect external contracts that also route fees here.
 * All percentages are expressed in basis points (1 bps = 0.01%).
 */

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IFundReceiver {
    /// @notice Called when FundManager forwards funds to an external pool.
    function depositRewards(uint256 amount) external;
}

contract FundManager {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS        = 10_000;
    uint256 public constant MAX_OWNERS     = 5;
    uint256 public constant MAX_CONTRACTS  = 10;

    // ─── State ────────────────────────────────────────────────────────────────
    address public token;                   // ERC-20 managed (new H2O)

    address[] public owners;

    /// Connected external contracts (staking, mining, etc.) that this manager
    /// can forward reward funds to.
    address[] public connectedContracts;

    /// Percentage of incoming funds routed to the reward pool (basis points).
    uint256 public rewardFundBps = 6_000;   // 60 %

    /// Percentage of incoming funds split among owners' wallets.
    uint256 public ownerWalletBps = 2_000;  // 20 %

    /// Percentage that stays in the contract (buffer / emergency).
    /// = MAX_BPS - rewardFundBps - ownerWalletBps (enforced on config update).

    /// Index of the connected contract that receives reward funds.
    /// If 0xFF, distribution is skipped (no receiver connected yet).
    uint8 public rewardReceiverIndex = 0xFF;

    bool public paused;

    // ─── Events ───────────────────────────────────────────────────────────────
    event Funded(address indexed from, uint256 amount);
    event Distributed(uint256 toRewardPool, uint256 toOwners, uint256 retained);
    event ContractConnected(address indexed contractAddr, uint256 index);
    event ContractDisconnected(address indexed contractAddr);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event ConfigUpdated(uint256 rewardFundBps, uint256 ownerWalletBps);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "FundManager: not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "FundManager: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _token, address _initialOwner) {
        require(_token != address(0), "zero token");
        require(_initialOwner != address(0), "zero owner");
        token = _token;
        owners.push(_initialOwner);
    }

    // ─── Funding ──────────────────────────────────────────────────────────────

    /**
     * @notice Anyone can fund the manager with `amount` tokens.
     *         Automatically distributes according to current config.
     */
    function fund(uint256 amount) external whenNotPaused {
        require(amount > 0, "zero amount");
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "transfer failed"
        );
        emit Funded(msg.sender, amount);
        _distribute(amount);
    }

    /**
     * @notice Internal entry-point for other connected contracts routing fees here.
     *         Called by e.g. NewH2OStaking when collecting deposit/withdraw fees.
     */
    function receiveFee(uint256 amount) external whenNotPaused {
        // Caller must have already transferred `amount` tokens to this contract,
        // or this contract must have allowance. For simplicity we pull from caller.
        require(amount > 0, "zero amount");
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "transfer failed"
        );
        emit Funded(msg.sender, amount);
        _distribute(amount);
    }

    // ─── Distribution ─────────────────────────────────────────────────────────

    function _distribute(uint256 amount) internal {
        uint256 toReward  = (amount * rewardFundBps)   / MAX_BPS;
        uint256 toOwners  = (amount * ownerWalletBps)  / MAX_BPS;
        uint256 retained  = amount - toReward - toOwners;

        // Forward to reward pool
        if (toReward > 0 && rewardReceiverIndex != 0xFF && connectedContracts.length > rewardReceiverIndex) {
            address receiver = connectedContracts[rewardReceiverIndex];
            if (receiver != address(0)) {
                IERC20(token).transfer(receiver, toReward);
                IFundReceiver(receiver).depositRewards(toReward);
            } else {
                retained += toReward;
            }
        } else {
            retained += toReward;
        }

        // Split among owners
        if (toOwners > 0 && owners.length > 0) {
            uint256 perOwner = toOwners / owners.length;
            uint256 dust = toOwners - perOwner * owners.length;
            for (uint256 i = 0; i < owners.length; i++) {
                if (owners[i] != address(0)) {
                    IERC20(token).transfer(owners[i], perOwner);
                }
            }
            retained += dust;
        }

        emit Distributed(toReward, toOwners, retained);
    }

    /**
     * @notice Manually trigger distribution of the contract's current balance.
     *         Useful if tokens were sent directly (not via fund()).
     */
    function distributeBalance() external onlyOwner {
        uint256 bal = IERC20(token).balanceOf(address(this));
        require(bal > 0, "nothing to distribute");
        _distribute(bal);
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    /**
     * @notice Update distribution percentages.
     * @param _rewardFundBps  Basis points for reward pool (e.g. 6000 = 60%).
     * @param _ownerWalletBps Basis points for owner wallets (e.g. 2000 = 20%).
     *        Remainder stays in contract.  Sum must be <= MAX_BPS.
     */
    function setDistribution(uint256 _rewardFundBps, uint256 _ownerWalletBps) external onlyOwner {
        require(_rewardFundBps + _ownerWalletBps <= MAX_BPS, "exceeds 100%");
        rewardFundBps  = _rewardFundBps;
        ownerWalletBps = _ownerWalletBps;
        emit ConfigUpdated(_rewardFundBps, _ownerWalletBps);
    }

    /// @notice Set which connected contract index receives the reward pool share.
    function setRewardReceiver(uint8 index) external onlyOwner {
        rewardReceiverIndex = index;
    }

    // ─── Contract Connections ─────────────────────────────────────────────────

    function connectContract(address contractAddr) external onlyOwner {
        require(contractAddr != address(0), "zero address");
        require(connectedContracts.length < MAX_CONTRACTS, "max contracts");
        connectedContracts.push(contractAddr);
        emit ContractConnected(contractAddr, connectedContracts.length - 1);
    }

    function disconnectContract(uint256 index) external onlyOwner {
        require(index < connectedContracts.length, "out of bounds");
        emit ContractDisconnected(connectedContracts[index]);
        connectedContracts[index] = address(0);
        // Reset reward receiver if it was pointing here
        if (rewardReceiverIndex == uint8(index)) rewardReceiverIndex = 0xFF;
    }

    function getConnectedContracts() external view returns (address[] memory) {
        return connectedContracts;
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause ────────────────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    // ─── Emergency ────────────────────────────────────────────────────────────

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "zero address");
        IERC20(token).transfer(to, amount);
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }

    function contractBalance() external view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }
}

contracts/NewAcuaSwapRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title NewAcuaSwapRouter
 * @notice Universal swap router for Acua 2.0 that aggregates Uniswap v2, v3, and v4.
 *
 * Features:
 *   - No swap amount limits
 *   - Configurable protocol fee (bps) per route, forwarded to FundManager
 *   - Supports Permit2 for input token approval (World App compatible)
 *   - Owner-configurable router addresses (upgradeable without redeployment)
 *   - Multi-hop via v3 encoded path or v2 path array
 *   - V4 swap via PoolManager (Uniswap v4) with custom hook support
 *   - Connect / disconnect contracts (fee collector, referral, etc.)
 *   - Add / remove owners
 *   - Emergency pause
 */

interface IERC20Swap {
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IPermit2Swap {
    struct TokenPermissions { address token; uint256 amount; }
    struct PermitTransferFrom { TokenPermissions permitted; uint256 nonce; uint256 deadline; }
    struct SignatureTransferDetails { address to; uint256 requestedAmount; }
    function permitTransferFrom(
        PermitTransferFrom calldata permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes calldata signature
    ) external;
}

// ─── Uniswap V2 ───────────────────────────────────────────────────────────────
interface IUniswapV2Router {
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);

    function getAmountsOut(uint256 amountIn, address[] calldata path)
        external view returns (uint256[] memory amounts);
}

// ─── Uniswap V3 ───────────────────────────────────────────────────────────────
interface ISwapRouter03 {
    struct ExactInputParams {
        bytes   path;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }
    function exactInput(ExactInputParams calldata params) external payable returns (uint256 amountOut);

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }
    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
}

// ─── Uniswap V4 (PoolManager) ─────────────────────────────────────────────────
interface IPoolManager {
    struct PoolKey {
        address currency0;
        address currency1;
        uint24  fee;
        int24   tickSpacing;
        address hooks;
    }
    struct SwapParams {
        bool    zeroForOne;
        int256  amountSpecified;
        uint160 sqrtPriceLimitX96;
    }
    function swap(PoolKey calldata key, SwapParams calldata params, bytes calldata hookData)
        external returns (int256 delta0, int256 delta1);
}

contract NewAcuaSwapRouter {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS       = 10_000;
    uint256 public constant MAX_FEE_BPS   = 500;     // 5% hard cap on protocol fee
    uint256 public constant MAX_OWNERS    = 5;
    uint256 public constant MAX_CONTRACTS = 10;

    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    // ─── Routers (configurable) ───────────────────────────────────────────────
    address public routerV2;    // Uniswap V2 (or SushiSwap / compatible)
    address public routerV3;    // Uniswap V3 SwapRouter02
    address public poolManagerV4; // Uniswap V4 PoolManager

    // ─── Protocol fee ─────────────────────────────────────────────────────────
    /// Basis points charged on every swap, forwarded to feeReceiver.
    uint256 public protocolFeeBps = 30;  // 0.3% default

    /// Where protocol fees are sent (FundManager or direct wallet).
    address public feeReceiver;

    // ─── Owner & Contract management ─────────────────────────────────────────
    address[] public owners;
    address[] public connectedContracts;
    bool public paused;

    // ─── Events ───────────────────────────────────────────────────────────────
    event SwapV2Executed(address indexed user, address indexed tokenIn, address indexed tokenOut, uint256 amountIn, uint256 amountOut, uint256 fee);
    event SwapV3Executed(address indexed user, uint256 amountIn, uint256 amountOut, uint256 fee);
    event SwapV4Executed(address indexed user, address tokenIn, address tokenOut, int256 delta0, int256 delta1);
    event RoutersUpdated(address v2, address v3, address v4);
    event FeeUpdated(uint256 bps, address receiver);
    event ContractConnected(address indexed addr);
    event ContractDisconnected(address indexed addr);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "AcuaSwap: not owner");
        _;
    }
    modifier whenNotPaused() {
        require(!paused, "AcuaSwap: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(
        address _initialOwner,
        address _routerV2,
        address _routerV3,
        address _poolManagerV4,
        address _feeReceiver
    ) {
        require(_initialOwner != address(0), "zero owner");
        owners.push(_initialOwner);
        routerV2       = _routerV2;
        routerV3       = _routerV3;
        poolManagerV4  = _poolManagerV4;
        feeReceiver    = _feeReceiver != address(0) ? _feeReceiver : _initialOwner;
    }

    // ─── V2 Swap ──────────────────────────────────────────────────────────────

    /**
     * @notice Swap exact tokens via Uniswap V2 (any V2-compatible DEX).
     * @param amountIn     Gross input amount (before protocol fee).
     * @param amountOutMin Minimum output (slippage protection, caller sets).
     * @param path         Token path [tokenIn, ..., tokenOut].
     * @param deadline     Unix timestamp deadline.
     */
    function swapV2(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        uint256 deadline
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV2 != address(0), "V2 router not set");
        require(path.length >= 2, "invalid path");
        require(amountIn > 0, "zero amount");

        address tokenIn  = path[0];
        address tokenOut = path[path.length - 1];

        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);

        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV2, netIn);

        uint256[] memory amounts = IUniswapV2Router(routerV2).swapExactTokensForTokens(
            netIn, amountOutMin, path, msg.sender, deadline
        );
        amountOut = amounts[amounts.length - 1];

        emit SwapV2Executed(msg.sender, tokenIn, tokenOut, amountIn, amountOut, fee);
    }

    /// @notice V2 swap with Permit2 input approval.
    function swapV2Permit2(
        IPermit2Swap.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amountOutMin,
        address[] calldata path,
        uint256 deadline
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV2 != address(0), "V2 router not set");
        require(path.length >= 2, "invalid path");

        uint256 amountIn = permit.permitted.amount;
        address tokenIn  = permit.permitted.token;
        address tokenOut = path[path.length - 1];

        IPermit2Swap(PERMIT2).permitTransferFrom(
            permit,
            IPermit2Swap.SignatureTransferDetails({ to: address(this), requestedAmount: amountIn }),
            msg.sender,
            signature
        );

        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV2, netIn);
        uint256[] memory amounts = IUniswapV2Router(routerV2).swapExactTokensForTokens(
            netIn, amountOutMin, path, msg.sender, deadline
        );
        amountOut = amounts[amounts.length - 1];

        emit SwapV2Executed(msg.sender, tokenIn, tokenOut, amountIn, amountOut, fee);
    }

    // ─── V3 Swap ──────────────────────────────────────────────────────────────

    /**
     * @notice Swap via Uniswap V3 using an encoded multi-hop path.
     * @param tokenIn     Input token.
     * @param encodedPath ABI-encoded V3 path (tokenIn · fee · tokenMid · fee · tokenOut …).
     * @param amountIn    Gross input amount.
     * @param amountOutMin Slippage protection.
     */
    function swapV3(
        address tokenIn,
        bytes calldata encodedPath,
        uint256 amountIn,
        uint256 amountOutMin
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV3 != address(0), "V3 router not set");
        require(amountIn > 0, "zero amount");

        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);

        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV3, netIn);
        amountOut = ISwapRouter03(routerV3).exactInput(
            ISwapRouter03.ExactInputParams({
                path:             encodedPath,
                recipient:        msg.sender,
                amountIn:         netIn,
                amountOutMinimum: amountOutMin
            })
        );

        emit SwapV3Executed(msg.sender, amountIn, amountOut, fee);
    }

    /// @notice Single-hop V3 swap (simpler interface).
    function swapV3Single(
        address tokenIn,
        address tokenOut,
        uint24  poolFee,
        uint256 amountIn,
        uint256 amountOutMin
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV3 != address(0), "V3 router not set");
        require(amountIn > 0, "zero amount");

        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV3, netIn);
        amountOut = ISwapRouter03(routerV3).exactInputSingle(
            ISwapRouter03.ExactInputSingleParams({
                tokenIn:           tokenIn,
                tokenOut:          tokenOut,
                fee:               poolFee,
                recipient:         msg.sender,
                amountIn:          netIn,
                amountOutMinimum:  amountOutMin,
                sqrtPriceLimitX96: 0
            })
        );

        emit SwapV3Executed(msg.sender, amountIn, amountOut, fee);
    }

    // ─── V4 Swap ──────────────────────────────────────────────────────────────

    /**
     * @notice Swap via Uniswap V4 PoolManager.
     * @dev Caller provides a fully-formed PoolKey and SwapParams.
     *      The actual settlement / currency router wrapping is handled by the
     *      Universal Router or a custom unlock callback (not included here —
     *      integrate via a separate UnlockCallback contract if needed).
     *      This is the raw hook into the V4 pool.
     */
    function swapV4(
        IPoolManager.PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata hookData,
        uint256 amountIn
    ) external whenNotPaused returns (int256 delta0, int256 delta1) {
        require(poolManagerV4 != address(0), "V4 pool manager not set");
        require(amountIn > 0, "zero amount");

        address tokenIn = params.zeroForOne ? key.currency0 : key.currency1;
        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 fee = _collectFee(tokenIn, amountIn);

        // Approve pool manager
        IERC20Swap(tokenIn).approve(poolManagerV4, amountIn - fee);

        (delta0, delta1) = IPoolManager(poolManagerV4).swap(key, params, hookData);

        emit SwapV4Executed(msg.sender, tokenIn, params.zeroForOne ? key.currency1 : key.currency0, delta0, delta1);
    }

    // ─── Fee ──────────────────────────────────────────────────────────────────

    function _collectFee(address tokenIn, uint256 amountIn) internal returns (uint256 fee) {
        if (protocolFeeBps == 0 || feeReceiver == address(0)) return 0;
        fee = (amountIn * protocolFeeBps) / MAX_BPS;
        if (fee > 0) {
            IERC20Swap(tokenIn).transfer(feeReceiver, fee);
        }
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    function setRouters(address _v2, address _v3, address _v4) external onlyOwner {
        routerV2      = _v2;
        routerV3      = _v3;
        poolManagerV4 = _v4;
        emit RoutersUpdated(_v2, _v3, _v4);
    }

    function setProtocolFee(uint256 _bps, address _receiver) external onlyOwner {
        require(_bps <= MAX_FEE_BPS, "fee too high");
        protocolFeeBps = _bps;
        feeReceiver    = _receiver;
        emit FeeUpdated(_bps, _receiver);
    }

    // ─── Contract Connections ─────────────────────────────────────────────────

    function connectContract(address contractAddr) external onlyOwner {
        require(contractAddr != address(0), "zero address");
        require(connectedContracts.length < MAX_CONTRACTS, "max contracts");
        connectedContracts.push(contractAddr);
        emit ContractConnected(contractAddr);
    }

    function disconnectContract(uint256 index) external onlyOwner {
        require(index < connectedContracts.length, "out of bounds");
        emit ContractDisconnected(connectedContracts[index]);
        connectedContracts[index] = address(0);
    }

    function getConnectedContracts() external view returns (address[] memory) {
        return connectedContracts;
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause / Emergency ────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function rescueToken(address _token, address to, uint256 amount) external onlyOwner {
        IERC20Swap(_token).transfer(to, amount);
    }

    // ─── Quote helpers (view) ─────────────────────────────────────────────────

    function quoteV2(uint256 amountIn, address[] calldata path)
        external view returns (uint256 amountOut)
    {
        require(routerV2 != address(0), "V2 router not set");
        uint256 fee = (amountIn * protocolFeeBps) / MAX_BPS;
        uint256[] memory amounts = IUniswapV2Router(routerV2).getAmountsOut(amountIn - fee, path);
        return amounts[amounts.length - 1];
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }
}

